<template><div class="overlay" @click.self="$emit('close')"><form @submit.prevent="save"><header><span>●</span><h2>{{ zone?'Modifier la zone':'Ajouter une zone d’intervention' }}</h2><button type="button" @click="$emit('close')">×</button></header><label>Région / Ville <b>*</b><select v-model="form.city" required><option value="" disabled>Sélectionner une région ou une ville</option><option>Dakar</option><option>Thiès</option><option>Saint-Louis</option><option>Diourbel</option></select></label><label>Zones / Quartiers couverts <b>*</b><textarea v-model.trim="form.districts" required maxlength="120" placeholder="Ex: Dakar Plateau, Medina, Fass…"></textarea></label><small>{{form.districts.length}}/120</small><p v-if="erreur" class="erreur">{{ erreur }}</p><div class="coverage"><strong>Statut de couverture</strong><label><input v-model="form.active" type="checkbox"><i></i>{{form.active?'Active':'Inactive'}}</label></div><footer><button class="cancel" type="button" @click="$emit('close')">Annuler</button><button class="save">▣ &nbsp; Enregistrer</button></footer></form></div></template>
<script setup>import{reactive,ref,watch}from'vue';import{minLengthMessage,requiredMessage}from'../../utils/formValidation';const props=defineProps({zone:{type:Object,default:null}});const emit=defineEmits(['close','save']);const form=reactive({city:'',districts:'',active:true});const erreur=ref('');watch(()=>props.zone,z=>Object.assign(form,z?{city:z.city,districts:z.districts,active:z.active}:{city:'',districts:'',active:true}),{immediate:true});function save(){erreur.value='';const messages=[requiredMessage(form.city,'La région / ville'),minLengthMessage(form.districts,'Les zones couvertes',3)].filter(Boolean);if(messages.length){erreur.value=messages[0];return}emit('save',{...form})}</script>
<style scoped>.overlay{position:fixed;inset:0;z-index:30;background:#09285138;display:grid;place-items:center}.overlay form{width:405px;background:#fff;border-radius:11px;padding:14px 18px 18px;box-shadow:0 18px 45px #09285135;color:#174b50}.overlay header{display:flex;align-items:center;gap:12px;margin-bottom:16px}.overlay header>span{width:37px;height:37px;display:grid;place-items:center;border-radius:9px;background:#e5f4f0;color:#087f70;font-size:27px}.overlay h2{margin:0;font-size:17px;flex:1}.overlay header button{font-size:27px;color:#087f70;background:transparent}.overlay>form>label{display:block;font-size:12px;font-weight:800;margin-top:15px}.overlay b{color:#ff3a54}.overlay select,.overlay textarea{display:block;width:100%;font:inherit;font-size:12px;color:#6381b5;border:1px solid #c5ddff;border-radius:8px;margin-top:7px;padding:11px;background:#fff;outline-color:#087f70}.overlay textarea{height:105px;resize:none}.overlay small{display:block;text-align:right;color:#6582b6;font-size:10px;margin-top:-16px;padding-right:8px}.erreur{margin:8px 0 0;color:#d43b50;font-size:11px;font-weight:700}.coverage{margin-top:18px;font-size:12px}.coverage strong{display:block;margin-bottom:9px}.coverage label{display:flex;align-items:center;gap:9px}.coverage input{display:none}.coverage i{width:43px;height:24px;border-radius:20px;background:#b7c8de;position:relative}.coverage i:after{content:'';position:absolute;width:18px;height:18px;top:3px;left:3px;background:#fff;border-radius:50%;transition:.2s}.coverage input:checked+i{background:#07b77b}.coverage input:checked+i:after{left:22px}footer{display:flex;justify-content:flex-end;gap:11px;margin-top:28px}footer button{padding:11px 17px;border-radius:8px;font-size:12px}.cancel{background:#fff;border:1px solid #c7dcf7;color:#45649a}.save{background:#087f70;color:#fff}</style>
